import{_ as e,r as n,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Валидация - October CMS - 3.x","titleTemplate":false,"description":"Валидация отправки форм с помощью AJAX-фреймворка.","frontmatter":{"subtitle":"Валидация отправки форм с помощью AJAX-фреймворка."},"headers":[{"level":2,"title":"Flash-валидация","slug":"flash-валидация","link":"#flash-валидация","children":[]},{"level":2,"title":"Встроенная валидация","slug":"встроенная-валидация","link":"#встроенная-валидация","children":[{"level":3,"title":"Валидация отдельного поля","slug":"валидация-отдельного-поля","link":"#валидация-отдельного-поля","children":[]}]},{"level":2,"title":"Использование сервиса валидации","slug":"использование-сервиса-валидации","link":"#использование-сервиса-валидации","children":[{"level":3,"title":"Пользовательские сообщения об ошибках и атрибуты","slug":"пользовательские-сообщения-об-ошибках-и-атрибуты","link":"#пользовательские-сообщения-об-ошибках-и-атрибуты","children":[]}]},{"level":2,"title":"Отображение сообщений об ошибках","slug":"отображение-сообщении-об-ошибках","link":"#отображение-сообщении-об-ошибках","children":[{"level":3,"title":"Отображение ошибок рядом с полями","slug":"отображение-ошибок-рядом-с-полями","link":"#отображение-ошибок-рядом-с-полями","children":[]},{"level":3,"title":"Отображение ошибок с flash-сообщениями","slug":"отображение-ошибок-с-flash-сообщениями","link":"#отображение-ошибок-с-flash-сообщениями","children":[]}]},{"level":2,"title":"Работа с JavaScript","slug":"работа-с-javascript","link":"#работа-с-javascript","children":[]},{"level":2,"title":"Полный пример использования","slug":"полныи-пример-использования","link":"#полныи-пример-использования","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/cms/features/validation.md","filePath":"3.x/ru/cms/features/validation.md"}'),i={name:"3.x/ru/cms/features/validation.md"};function k(r,a,g,d,m,h){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"Валидация",-1)),s(p),a[1]||(a[1]=u(`<p>Валидация форм проверяет пользовательский ввод по набору предопределённых правил. При использовании <a href="./../ajax/introduction.html">AJAX-фреймворка</a> валидация формы происходит без специальной настройки — недопустимое поле получает фокус и отображается сообщение об ошибке (обычно в виде окна alert).</p><h2 id="flash-валидация"><a href="#flash-валидация" class="header-anchor">#</a> Flash-валидация</h2><p>Для базовой валидации добавление <a href="./flash-messages.html">атрибута <code>data-request-flash</code></a> на HTML-тег формы обеспечивает простой и понятный интерфейс для отображения сообщений валидации и обычно достаточно для большинства реализаций.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmit<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-flash</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Name<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>name<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Submit
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Внутри вашего <a href="./../ajax/handlers.html">AJAX-обработчика</a> вы можете сгенерировать <a href="./../../extend/system/exceptions.html">исключение валидации</a> с помощью класса <code>ValidationException</code>, чтобы сделать поле недопустимым. Передаваемый массив (первый аргумент) должен использовать имена полей в качестве ключей и сообщения об ошибках в качестве значений.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSubmit</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;You must give a name!&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Когда AJAX-фреймворк обнаруживает <code>ValidationException</code>, он автоматически устанавливает фокус на первое недопустимое поле и отображает сообщения об ошибках, если они настроены.</p><h2 id="встроенная-валидация"><a href="#встроенная-валидация" class="header-anchor">#</a> Встроенная валидация</h2><p>Для более комплексной валидации можно включить встроенную валидацию, добавив атрибут <code>data-request-validate</code> на HTML-тег формы. Ниже приведён минимальный пример валидации формы с использованием этого подхода, где сообщение об ошибке отображается внутри формы.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmit<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-validate</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-danger<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-validate-error</span><span class="token punctuation">&gt;</span></span>
        <span class="token comment">&lt;!-- Validation Message --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Name<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>name<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Submit
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="валидация-отдельного-поля"><a href="#валидация-отдельного-поля" class="header-anchor">#</a> Валидация отдельного поля</h3><p>В некоторых случаях вам может потребоваться валидировать отдельное поле при изменении его значения. Добавив атрибут <code>data-track-input</code> вместе с атрибутом <code>data-request</code>, AJAX-фреймворк будет отправлять запрос, когда пользователь вводит что-то в поле.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request-validate</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Username<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>username<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onCheckUsername<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-track-input</span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Для валидации поля можно использовать отдельный AJAX-обработчик. Если исключение не сгенерировано, поле считается допустимым.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onCheckUsername</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;username&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Username is taken!&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="использование-сервиса-валидации"><a href="#использование-сервиса-валидации" class="header-anchor">#</a> Использование сервиса валидации</h2><div class="custom-block aside"><p>Обратитесь к <a href="./../../extend/services/validation.html">статье о валидации</a>, чтобы узнать о различных правилах, которые можно использовать.</p></div><p>Для более сложной валидации вы можете использовать фасад <code>Request</code> для массового применения правил к пользовательскому вводу. Метод <code>validate</code> выполняет валидацию по указанным правилам (первый аргумент) и возвращает массив проверенных атрибутов и значений. Он также генерирует <code>ValidationException</code> при неудачной валидации.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSubmit</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$data</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">validate</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|email&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// The code will not reach here if validation fails</span>

    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Jobs done!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="пользовательские-сообщения-об-ошибках-и-атрибуты"><a href="#пользовательские-сообщения-об-ошибках-и-атрибуты" class="header-anchor">#</a> Пользовательские сообщения об ошибках и атрибуты</h3><p>Чтобы изменить стандартные сообщения валидации, передайте пользовательские сообщения в метод <code>validate</code>. Ключи в массиве сообщений (третий аргумент) следуют формату <code>атрибут.правило</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$messages</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;email.required&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Please type something for the email...&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;email.email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;That email is not an email...!&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token variable">$data</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">validate</span><span class="token punctuation">(</span><span class="token variable">$rules</span><span class="token punctuation">,</span> <span class="token variable">$messages</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите сохранить стандартные сообщения валидации и изменить только имя <code>:attribute</code>, передайте пользовательские атрибуты в виде массива (четвёртый аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$attributeNames</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;e-mail address&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token variable">$data</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">validate</span><span class="token punctuation">(</span><span class="token variable">$rules</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$attributeNames</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="отображение-сообщении-об-ошибках"><a href="#отображение-сообщении-об-ошибках" class="header-anchor">#</a> Отображение сообщений об ошибках</h2><p>Внутри формы вы можете отобразить первое сообщение об ошибке, используя атрибут <code>data-validate-error</code> на элементе-контейнере. Содержимое контейнера будет заменено сообщением об ошибке, а элемент станет видимым.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-validate-error</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Для отображения нескольких сообщений об ошибках добавьте элемент с атрибутом <code>data-message</code>. В этом примере тег paragraph будет продублирован для каждого существующего сообщения.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-danger<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-validate-error</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span> <span class="token attr-name">data-message</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="отображение-ошибок-рядом-с-полями"><a href="#отображение-ошибок-рядом-с-полями" class="header-anchor">#</a> Отображение ошибок рядом с полями</h3><p>Если вы предпочитаете показывать сообщения валидации для отдельных полей, определите элемент с атрибутом <code>data-validate-for</code>, передав имя поля в качестве значения.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Input field --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>phone<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>

<span class="token comment">&lt;!-- Validation message for the field --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-validate-for</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>phone<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Если элемент оставлен пустым, он будет заполнен текстом валидации от сервера. В противном случае можно указать произвольный текст, который будет отображаться вместо серверного.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-validate-for</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>phone<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Oops.. phone number is invalid!
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="отображение-ошибок-с-flash-сообщениями"><a href="#отображение-ошибок-с-flash-сообщениями" class="header-anchor">#</a> Отображение ошибок с flash-сообщениями</h3><p>При использовании атрибута <code>data-request-validate</code> совместно с <a href="./flash-messages.html">атрибутом <code>data-request-flash</code></a> ошибки валидации имеют приоритет и подавляют flash-сообщение. Чтобы отобразить оба одновременно, установите значение атрибута в подстановочный символ (<code>*</code>) для отображения всех типов flash-сообщений, включая валидацию.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
    <span class="token attr-name">data-request-validate</span>
    <span class="token attr-name">data-request-flash</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>*<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="работа-с-javascript"><a href="#работа-с-javascript" class="header-anchor">#</a> Работа с JavaScript</h2><p>Для реализации пользовательской обработки сообщений об ошибках используйте событие <code>ajax:invalid-field</code> для отображения поля и <code>ajax:promise</code> для сброса формы при новой отправке. Используемые JavaScript-события описаны в <a href="./../ajax/javascript-api.html">AJAX JavaScript API</a>.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:invalid-field&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">const</span> <span class="token punctuation">{</span> element<span class="token punctuation">,</span> fieldName<span class="token punctuation">,</span> errorMsg<span class="token punctuation">,</span> isFirst <span class="token punctuation">}</span> <span class="token operator">=</span> event<span class="token punctuation">.</span>detail<span class="token punctuation">;</span>
    element<span class="token punctuation">.</span>classList<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token string">&#39;has-error&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:promise&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    event<span class="token punctuation">.</span>target<span class="token punctuation">.</span><span class="token function">closest</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;.has-error&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">el</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        el<span class="token punctuation">.</span>classList<span class="token punctuation">.</span><span class="token function">remove</span><span class="token punctuation">(</span><span class="token string">&#39;has-error&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="полныи-пример-использования"><a href="#полныи-пример-использования" class="header-anchor">#</a> Полный пример использования</h2><p>Ниже приведён полный пример валидации формы. Он вызывает обработчик <code>onSubmitForm</code>, который запускает индикатор загрузки на кнопке, выполняет валидацию полей формы, затем отображает успешное flash-сообщение.</p><p>Атрибут <code>data-request-flash</code> используется для <a href="./flash-messages.html">включения flash-сообщений</a> для успешных сообщений и отображения сообщений валидации. Атрибут <code>data-attach-loading</code> используется для отображения <a href="./loaders.html">индикатора загрузки</a> и предотвращения повторных отправок из-за случайных кликов.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmitForm<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-validate</span>
    <span class="token attr-name">data-request-flash</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Username<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>username<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onCheckUsername<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-track-input</span>
            <span class="token attr-name">data-attach-loading</span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">data-validate-for</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>username<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Email<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>email<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">data-validate-for</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>email<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Submit
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-danger<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-validate-error</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span> <span class="token attr-name">data-message</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>AJAX-обработчик <code>onSubmitForm</code> анализирует POST-данные, отправленные клиентом, и применяет правила к валидатору. Если валидация не проходит, генерируется <code>ValidationException</code>, в противном случае возвращается сообщение <code>Flash::success</code>.</p><p>Обработчик <code>onCheckUsername</code> проверяет доступность имени пользователя — в данном случае жёстко запрещены имена <strong>admin</strong> и <strong>jeff</strong>. Проверка выполняется дважды: при вводе текста пользователем и при отправке формы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSubmitForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$data</span> <span class="token operator">=</span> <span class="token class-name static-context">Request</span><span class="token operator">::</span><span class="token function">validate</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;username&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;required|email&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">onCheckUsername</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Jobs done!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">function</span> <span class="token function-definition function">onCheckUsername</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$username</span> <span class="token operator">=</span> <span class="token function">strtolower</span><span class="token punctuation">(</span><span class="token function">trim</span><span class="token punctuation">(</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;username&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$isTaken</span> <span class="token operator">=</span> <span class="token function">in_array</span><span class="token punctuation">(</span><span class="token variable">$username</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;admin&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;jeff&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$isTaken</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;username&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Username is taken!&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../extend/services/validation.html">Сервис валидации</a></li><li><a href="./../../extend/database/traits.html">Трейт валидации</a></li></ul></div>`,49))])}const q=e(i,[["render",k]]);export{f as __pageData,q as default};
